using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Threading;using System.Windows.Media;using System.Windows.Media.Imaging;
class ApkCheck{
 static void Pump(Task task){while(!task.IsCompleted){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);System.Threading.Thread.Sleep(3);}task.GetAwaiter().GetResult();}
 [STAThread]static int Main(){try{var app=new Application();System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());var tv=new TV();var inspect=typeof(TV).GetMethod("InspectApk",BindingFlags.Instance|BindingFlags.NonPublic);File.WriteAllText("apk-check.log","");foreach(string file in Directory.GetFiles(AppDomain.CurrentDomain.BaseDirectory+"apps","*.apk")){var task=(Task<TV.ApkInfo>)inspect.Invoke(tv,new object[]{file});Pump(task);var data=task.Result;if(data.Error!=null||string.IsNullOrWhiteSpace(data.Package)||string.IsNullOrWhiteSpace(data.Name))throw new Exception(file+": "+data.Error);File.AppendAllText("apk-check.log",data.Name+" | "+data.Package+" | "+data.Version+Environment.NewLine);}typeof(TV).GetMethod("Show",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tv,new object[]{"安装与桌面"});var content=(FrameworkElement)tv.Content;content.Measure(new Size(1420,1040));content.Arrange(new Rect(0,0,1420,1040));content.UpdateLayout();var bmp=new RenderTargetBitmap(1420,1040,96,96,PixelFormats.Pbgra32);bmp.Render(content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create("apk-page.png"))encoder.Save(file);return 0;}catch(Exception ex){File.WriteAllText("apk-check-error.log",ex.ToString());return 1;}}
}
